package com.team.ecommerce.order.controller;

import com.team.ecommerce.order.promotion.PromotionService;
import com.team.ecommerce.order.promotion.PromotionEvents;
import com.team.ecommerce.order.service.CommerceFinanceService;
import com.team.ecommerce.shared.dto.ApiResponse;
import com.team.ecommerce.shared.exception.BadRequestException;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.*;

@RestController @RequestMapping("/api/v1/orders/operations") @RequiredArgsConstructor
@Transactional("orderTransactionManager")
public class CommerceOperationsController {
 private final JdbcTemplate db; private final PromotionService promotions;private final CommerceFinanceService finance;private final PromotionEvents events;
 private void admin(Long user){if(user==null||!promotions.admin(user))throw new AccessDeniedException("Chỉ quản trị viên được truy cập.");}
 private long shop(Long user){if(user==null)throw new AccessDeniedException("Hãy đăng nhập.");Long id=promotions.shop(user);if(id==null)throw new AccessDeniedException("Tài khoản chưa có shop đang hoạt động.");return id;}
 private void audit(long user,String action,String type,long id,String reason){db.update("INSERT INTO commerce_audit(actor_id,action,entity_type,entity_id,reason) VALUES(?,?,?,?,?)",user,action,type,id,reason);}
 private String reason(Map<String,Object> input){String reason=Objects.toString(input.get("reason"),"").trim();if(reason.length()<5||reason.length()>500)throw new BadRequestException("Nhập lý do từ 5 đến 500 ký tự.");return reason;}
 @GetMapping("/seller/summary") public ApiResponse<?> seller(@AuthenticationPrincipal Long user,@RequestParam(defaultValue="30") int days){long id=shop(user);return ApiResponse.success(finance.report(id,days));}
 @PutMapping("/seller/sales/{id}") public ApiResponse<?> sale(@AuthenticationPrincipal Long user,@PathVariable long id,@RequestBody Map<String,Integer> input){long owner=shop(user);if(db.queryForObject("SELECT COUNT(*) FROM product_db.products WHERE id=? AND shop_id=? AND deleted_at IS NULL",Long.class,id,owner)==0)throw new AccessDeniedException("Sản phẩm không thuộc shop.");int percent=input.getOrDefault("percent",0),days=input.getOrDefault("days",30);if(percent<0||percent>=100||days<1||days>366)throw new BadRequestException("Giảm từ 0 đến 99%, trong 1–366 ngày.");if(percent==0)db.update("DELETE FROM commerce_product_sales WHERE product_id=?",id);else db.update("INSERT INTO commerce_product_sales(product_id,discount_percent,created_by,starts_at,ends_at) VALUES(?,?,?,UTC_TIMESTAMP(3),DATE_ADD(UTC_TIMESTAMP(3),INTERVAL ? DAY)) ON DUPLICATE KEY UPDATE discount_percent=VALUES(discount_percent),starts_at=VALUES(starts_at),ends_at=VALUES(ends_at),created_by=VALUES(created_by)",id,percent,user,days);audit(user,"PRODUCT_SALE","PRODUCT",id,"Giảm "+percent+"% trong "+days+" ngày");events.enqueue("PRODUCT_SALE_CHANGED",Map.of("productId",id));return ApiResponse.success("Đã cập nhật giá khuyến mãi của shop");}
 @GetMapping("/seller/reviews") public ApiResponse<?> sellerReviews(@AuthenticationPrincipal Long user,@RequestParam(defaultValue="0") int page){long id=shop(user);return ApiResponse.success(db.queryForList("SELECT r.id,r.product_id AS productId,p.name AS productName,r.reviewer_name AS reviewerName,r.rating,r.content,r.seller_reply AS sellerReply,r.created_at AS createdAt FROM product_db.reviews r JOIN product_db.products p ON p.id=r.product_id WHERE p.shop_id=? AND r.deleted_at IS NULL AND r.status='VISIBLE' ORDER BY r.id DESC LIMIT 30 OFFSET ?",id,Math.max(page,0)*30));}
 @GetMapping("/seller/returns") public ApiResponse<?> returns(@AuthenticationPrincipal Long user,@RequestParam(defaultValue="0") int page){long id=shop(user);return ApiResponse.success(db.queryForList("SELECT o.id,o.order_no AS name,MIN(r.status) AS status,o.total_amount AS total,MAX(r.description) AS reason FROM order_returns r JOIN orders o ON o.id=r.order_id JOIN order_items i ON i.id=r.order_item_id WHERE i.shop_id=? GROUP BY o.id ORDER BY o.id DESC LIMIT 30 OFFSET ?",id,Math.max(0,page)*30));}
 @PatchMapping("/seller/returns/{id}") public ApiResponse<?> resolveReturn(@AuthenticationPrincipal Long user,@PathVariable long id,@RequestBody Map<String,Object> input){
  long shop=shop(user);String reason=reason(input),target=Objects.toString(input.get("status"),"");
  var orders=db.queryForList("SELECT id,user_id FROM orders WHERE id=? AND status='RETURNED' FOR UPDATE",id);
  if(orders.isEmpty()||db.queryForObject("SELECT COUNT(*) FROM order_items WHERE order_id=? AND (shop_id<>? OR shop_id IS NULL)",Integer.class,id,shop)>0)throw new AccessDeniedException("Không có yêu cầu trả hàng thuộc shop.");
  var rows=db.queryForList("SELECT * FROM order_returns WHERE order_id=? FOR UPDATE",id);
  String expected=Set.of("APPROVED","REJECTED").contains(target)?"REQUESTED":"RECEIVED".equals(target)?"APPROVED":"";
  if(rows.isEmpty()||expected.isEmpty()||rows.stream().anyMatch(r->!expected.equals(r.get("status"))))throw new BadRequestException("Bước xử lý trả hàng không hợp lệ.");
  db.update("UPDATE order_returns SET status=?,resolved_at=UTC_TIMESTAMP(3) WHERE order_id=?",target,id);
  if("REJECTED".equals(target))db.update("UPDATE orders SET status='DELIVERED' WHERE id=?",id);
  if("RECEIVED".equals(target)){
   db.update("UPDATE product_db.product_skus s JOIN order_items i ON i.sku_id=s.id SET s.stock_quantity=s.stock_quantity+i.quantity,s.sold_count=GREATEST(0,s.sold_count-i.quantity),s.version=COALESCE(s.version,0)+1 WHERE i.order_id=?",id);
   db.update("UPDATE product_db.products p JOIN (SELECT product_id,SUM(quantity) AS qty FROM order_items WHERE order_id=? GROUP BY product_id) i ON i.product_id=p.id SET p.sold_count=GREATEST(0,p.sold_count-i.qty)",id);
  }
  audit(user,"RETURN_"+target,"ORDER",id,reason);db.update("INSERT INTO auth_db.app_notifications(user_id,event_key,type,title,body,order_id) VALUES(?,?,'ORDER',?,?,?)",orders.get(0).get("user_id"),"return-"+id+"-"+target,"Cập nhật trả hàng #"+id,("APPROVED".equals(target)?"Shop đã đồng ý nhận lại hàng. Liên hệ shop để gửi hàng.":"RECEIVED".equals(target)?"Shop đã nhận lại hàng, đang chờ đối soát hoàn tiền.":"Shop từ chối yêu cầu trả hàng.")+" "+reason,id);events.enqueue("ORDER_STATUS_CHANGED",Map.of("orderId",id));return ApiResponse.success("Đã cập nhật yêu cầu trả hàng");
 }
 @PostMapping("/admin/orders/{id}/refund") public ApiResponse<?> recordRefund(@AuthenticationPrincipal Long user,@PathVariable long id,@RequestBody Map<String,Object> input){
  admin(user);String reason=reason(input),reference=Objects.toString(input.get("reference"),"").trim();if(reference.length()<6||reference.length()>120)throw new BadRequestException("Cần mã giao dịch/chứng từ hoàn tiền thực tế (6–120 ký tự).");
  var orders=db.queryForList("SELECT id,user_id,total_amount,payment_method_type,payment_status FROM orders WHERE id=? AND status='RETURNED' FOR UPDATE",id);if(orders.isEmpty())throw new BadRequestException("Đơn không ở trạng thái trả hàng.");
  if(!"PAID".equals(orders.get(0).get("payment_status")))throw new BadRequestException("Chỉ ghi nhận hoàn tiền cho đơn đã thanh toán.");
  BigDecimal amount;try{amount=new BigDecimal(Objects.toString(input.get("amount"),""));}catch(Exception e){throw new BadRequestException("Số tiền không hợp lệ.");}
  if(amount.signum()<=0||amount.compareTo(new BigDecimal(orders.get(0).get("total_amount").toString()))!=0)throw new BadRequestException("Luồng trả toàn đơn yêu cầu hoàn đúng tổng tiền đã chốt.");
  var rows=db.queryForList("SELECT status FROM order_returns WHERE order_id=? FOR UPDATE",id);if(rows.isEmpty()||rows.stream().anyMatch(r->!"RECEIVED".equals(r.get("status"))))throw new BadRequestException("Shop cần xác nhận đã nhận lại hàng trước.");
  if(db.queryForObject("SELECT COUNT(*) FROM commerce_refunds WHERE order_id=?",Long.class,id)>0)throw new BadRequestException("Đơn đã ghi nhận hoàn tiền.");
  db.update("INSERT INTO commerce_refunds(order_id,amount,transaction_reference,recorded_by) VALUES(?,?,?,?)",id,amount,reference,user);db.update("UPDATE order_returns SET status='REFUNDED',resolved_at=UTC_TIMESTAMP(3) WHERE order_id=?",id);db.update("UPDATE orders SET payment_status='REFUNDED' WHERE id=?",id);
  db.update("INSERT INTO auth_db.app_notifications(user_id,event_key,type,title,body,order_id) VALUES(?,?,'ORDER',?,?,?)",orders.get(0).get("user_id"),"refund-"+id,"Đã ghi nhận hoàn tiền đơn #"+id,"Số tiền "+java.text.NumberFormat.getIntegerInstance(Locale.forLanguageTag("vi-VN")).format(amount)+" ₫. Mã đối soát: "+reference+". "+reason,id);
  audit(user,"RECORD_MANUAL_REFUND","ORDER",id,reference+": "+reason);events.enqueue("ORDER_STATUS_CHANGED",Map.of("orderId",id));return ApiResponse.success("Đã ghi nhận chứng từ hoàn tiền. Thao tác này không tự chuyển tiền qua ngân hàng.");
 }
 @PutMapping("/seller/reviews/{id}/reply") public ApiResponse<?> reply(@AuthenticationPrincipal Long user,@PathVariable long id,@RequestBody Map<String,String> input){long shop=shop(user);String reply=Objects.toString(input.get("reply"),"").trim();if(reply.isEmpty()||reply.length()>2000)throw new BadRequestException("Phản hồi cần từ 1 đến 2.000 ký tự.");int changed=db.update("UPDATE product_db.reviews r JOIN product_db.products p ON p.id=r.product_id SET r.seller_reply=?,r.seller_replied_at=UTC_TIMESTAMP(3) WHERE r.id=? AND p.shop_id=? AND r.deleted_at IS NULL",reply,id,shop);if(changed==0)throw new AccessDeniedException("Đánh giá không thuộc shop.");audit(user,"REPLY_REVIEW","REVIEW",id,"Phản hồi khách hàng");return ApiResponse.success("Đã lưu phản hồi");}
 @GetMapping("/admin/summary") public ApiResponse<?> overview(@AuthenticationPrincipal Long user,@RequestParam(defaultValue="30") int days){admin(user);var data=finance.report(null,days);data.put("accounts",db.queryForObject("SELECT COUNT(*) FROM auth_db.users WHERE deleted_at IS NULL",Long.class));data.put("shops",db.queryForObject("SELECT COUNT(*) FROM product_db.shops WHERE deleted_at IS NULL",Long.class));data.put("products",db.queryForObject("SELECT COUNT(*) FROM product_db.products WHERE deleted_at IS NULL",Long.class));data.put("activeCampaigns",db.queryForObject("SELECT COUNT(*) FROM promo_campaigns WHERE status='ACTIVE' AND ends_at>UTC_TIMESTAMP(3)",Long.class));return ApiResponse.success(data);}
 @GetMapping("/admin/orders/{id}") public ApiResponse<?> orderDetails(@AuthenticationPrincipal Long user,@PathVariable long id){admin(user);var rows=db.queryForList("SELECT id,order_no AS name,status,payment_status AS paymentStatus,currency,total_amount AS total,recipient_name AS recipientName,recipient_phone AS recipientPhone,ship_address_line AS street,ship_ward AS ward,ship_district AS district,ship_province AS province,note FROM orders WHERE id=?",id);if(rows.isEmpty())throw new BadRequestException("Không tìm thấy đơn.");var result=rows.get(0);result.put("items",db.queryForList("SELECT product_name AS name,sku_name AS variant,quantity,unit_price AS price,line_total AS total FROM order_items WHERE order_id=? ORDER BY id",id));result.put("returns",db.queryForList("SELECT status,description,resolved_at AS resolvedAt FROM order_returns WHERE order_id=?",id));return ApiResponse.success(result);}
 @GetMapping("/admin/{type:users|shops|products|orders|reviews|audit}") public ApiResponse<?> list(@AuthenticationPrincipal Long user,@PathVariable String type,@RequestParam(defaultValue="") String keyword,@RequestParam(defaultValue="0") String status,@RequestParam(defaultValue="0") int page){
  admin(user);String q="%"+keyword.trim()+"%";int offset=Math.min(100000,Math.max(0,page))*30;
  String sql=switch(type){
   case "users" -> "SELECT u.id,u.full_name AS name,u.email,u.status,u.created_at AS createdAt,(SELECT GROUP_CONCAT(r.code) FROM auth_db.user_roles ur JOIN auth_db.roles r ON r.id=ur.role_id WHERE ur.user_id=u.id) AS roles FROM auth_db.users u WHERE u.deleted_at IS NULL AND (u.full_name LIKE ? OR u.email LIKE ?) ORDER BY u.id DESC LIMIT 30 OFFSET ?";
   case "shops" -> "SELECT s.id,s.name,s.logo_url AS image,s.province,s.status,u.email,COALESCE(f.vat_percent,0) AS vatPercent,COALESCE(f.commission_percent,0) AS commissionPercent FROM product_db.shops s JOIN auth_db.users u ON u.id=s.owner_user_id LEFT JOIN commerce_finance_policy f ON f.shop_id=s.id WHERE s.deleted_at IS NULL AND (s.name LIKE ? OR u.email LIKE ?) ORDER BY s.id DESC LIMIT 30 OFFSET ?";
   case "products" -> "SELECT p.id,p.name,p.status,p.min_price AS price,p.thumbnail_url AS image,s.name AS shop FROM product_db.products p JOIN product_db.shops s ON s.id=p.shop_id WHERE p.deleted_at IS NULL AND (p.name LIKE ? OR s.name LIKE ?) ORDER BY p.id DESC LIMIT 30 OFFSET ?";
   case "reviews" -> "SELECT r.id,p.name,p.thumbnail_url AS image,r.reviewer_name AS reviewer,r.content,r.rating,r.status FROM product_db.reviews r JOIN product_db.products p ON p.id=r.product_id WHERE r.deleted_at IS NULL AND (p.name LIKE ? OR r.content LIKE ?) ORDER BY r.id DESC LIMIT 30 OFFSET ?";
   case "orders" -> "SELECT o.id,o.order_no AS name,o.status,o.total_amount AS total,o.currency,o.payment_status AS paymentStatus,o.created_at AS createdAt,u.email FROM orders o JOIN auth_db.users u ON u.id=o.user_id WHERE o.currency='VND' AND (CONCAT(o.order_no,' ',o.id) LIKE ? OR u.email LIKE ?) ORDER BY o.id DESC LIMIT 30 OFFSET ?";
   default -> "SELECT id,action AS name,entity_type AS entityType,entity_id AS entityId,actor_id AS actorId,reason,created_at AS createdAt FROM commerce_audit WHERE (action LIKE ? OR reason LIKE ?) ORDER BY id DESC LIMIT 30 OFFSET ?";
  };
  var params=new ArrayList<Object>();params.add(q);params.add(q);
  if(!status.isBlank()&&!"0".equals(status)&&!"audit".equals(type)){String alias=switch(type){case "users"->"u";case "shops"->"s";case "products"->"p";case "reviews"->"r";default->"o";};int split=sql.lastIndexOf(" ORDER BY ");sql=sql.substring(0,split)+" AND "+alias+".status=?"+sql.substring(split);params.add(status);}
  long total=db.queryForObject("SELECT COUNT(*) FROM ("+sql.substring(0,sql.lastIndexOf(" ORDER BY "))+") matched",Long.class,params.toArray());params.add(offset);
  return ApiResponse.success(Map.of("items",db.queryForList(sql,params.toArray()),"page",Math.max(page,0),"totalElements",total));
 }
 @GetMapping("/admin/record/{type:users|shops|products|reviews}/{id}") public ApiResponse<?> record(@AuthenticationPrincipal Long user,@PathVariable String type,@PathVariable long id){
  admin(user);String sql=switch(type){case "users"->"SELECT id,full_name AS name,email,phone,status,created_at AS createdAt FROM auth_db.users WHERE id=? AND deleted_at IS NULL";case "shops"->"SELECT s.id,s.name,s.description,s.province,s.logo_url AS image,s.status,u.email FROM product_db.shops s JOIN auth_db.users u ON u.id=s.owner_user_id WHERE s.id=? AND s.deleted_at IS NULL";case "products"->"SELECT id,name,description,thumbnail_url AS image,status,min_price AS price FROM product_db.products WHERE id=? AND deleted_at IS NULL";default->"SELECT id,reviewer_name AS name,content,rating,status,product_id AS productId FROM product_db.reviews WHERE id=? AND deleted_at IS NULL";};var rows=db.queryForList(sql,id);if(rows.isEmpty())throw new BadRequestException("Không tìm thấy bản ghi.");var row=rows.get(0);row.put("recordType",type);
  if("products".equals(type))row.put("variants",db.queryForList("SELECT name,price,stock_quantity AS stock FROM product_db.product_skus WHERE product_id=? AND deleted_at IS NULL",id));
  if("shops".equals(type)){row.put("productCount",db.queryForObject("SELECT COUNT(*) FROM product_db.products WHERE shop_id=? AND deleted_at IS NULL",Long.class,id));var profiles=db.queryForList("SELECT profile_json FROM product_db.shop_business_profiles WHERE shop_id=?",String.class,id);if(!profiles.isEmpty())try{row.put("profile",new com.fasterxml.jackson.databind.ObjectMapper().readValue(profiles.get(0),Map.class));}catch(Exception ignored){}}
  if("users".equals(type))row.put("orderCount",db.queryForObject("SELECT COUNT(*) FROM orders WHERE user_id=?",Long.class,id));return ApiResponse.success(row);
 }
 @PatchMapping("/admin/{type:users|shops|products|reviews}/{id}") public ApiResponse<?> moderate(@AuthenticationPrincipal Long user,@PathVariable String type,@PathVariable long id,@RequestBody Map<String,Object> input){
  admin(user);String reason=reason(input),status=Objects.toString(input.get("status"),"");String table;Set<String> allowed;
  switch(type){case "users" -> {table="auth_db.users";allowed=Set.of("ACTIVE","LOCKED");if(id==user)throw new BadRequestException("Không tự khóa tài khoản đang dùng.");if(db.queryForObject("SELECT COUNT(*) FROM auth_db.user_roles ur JOIN auth_db.roles r ON r.id=ur.role_id WHERE ur.user_id=? AND r.code='ADMIN'",Integer.class,id)>0)throw new BadRequestException("Không khóa quản trị viên qua màn hình này.");}
   case "shops" -> {table="product_db.shops";allowed=Set.of("ACTIVE","SUSPENDED");}
   case "products" -> {table="product_db.products";allowed=Set.of("ACTIVE","HIDDEN","BANNED");if("ACTIVE".equals(status)&&db.queryForObject("SELECT COUNT(*) FROM product_db.products WHERE id=? AND (thumbnail_url IS NULL OR TRIM(thumbnail_url)='')",Integer.class,id)>0)throw new BadRequestException("Cần ảnh trước khi hiển thị sản phẩm.");}
   default -> {table="product_db.reviews";allowed=Set.of("VISIBLE","HIDDEN");}}
  if(!allowed.contains(status))throw new BadRequestException("Trạng thái không hợp lệ.");
  if(db.update("UPDATE "+table+" SET status=? WHERE id=? AND deleted_at IS NULL",status,id)==0)throw new BadRequestException("Không tìm thấy bản ghi.");
  if("users".equals(type)&&"LOCKED".equals(status))db.update("DELETE FROM auth_db.refresh_tokens WHERE user_id=?",id);
  if("shops".equals(type)&&!"ACTIVE".equals(status))db.update("UPDATE promo_campaigns SET status='CANCELLED' WHERE shop_id=?",id);
  if("reviews".equals(type))db.update("UPDATE product_db.products p JOIN product_db.reviews target ON target.product_id=p.id SET p.rating_count=(SELECT COUNT(*) FROM product_db.reviews r WHERE r.product_id=p.id AND r.deleted_at IS NULL AND r.status='VISIBLE'),p.rating_avg=COALESCE((SELECT AVG(r.rating) FROM product_db.reviews r WHERE r.product_id=p.id AND r.deleted_at IS NULL AND r.status='VISIBLE'),0) WHERE target.id=?",id);
  audit(user,"MODERATE_"+type.toUpperCase(Locale.ROOT),type,id,status+": "+reason);events.enqueue("CATALOG_CHANGED",Map.of("type",type,"id",id));return ApiResponse.success("Đã cập nhật và ghi nhật ký");
 }
 @PutMapping("/admin/shops/{id}/finance") public ApiResponse<?> policy(@AuthenticationPrincipal Long user,@PathVariable long id,@RequestBody Map<String,Object> input){admin(user);String reason=reason(input);if(db.queryForObject("SELECT COUNT(*) FROM product_db.shops WHERE id=? AND deleted_at IS NULL",Integer.class,id)==0)throw new BadRequestException("Shop không tồn tại.");try{finance.configure(user,id,new BigDecimal(Objects.toString(input.get("vatPercent"),"")),new BigDecimal(Objects.toString(input.get("commissionPercent"),"")));}catch(NumberFormatException e){throw new BadRequestException("Thuế và phí không hợp lệ.");}audit(user,"FINANCE_POLICY","SHOP",id,reason);return ApiResponse.success("Đã lưu. Chỉ áp dụng cho đơn đặt mới.");}
 @PostMapping("/admin/notifications") public ApiResponse<?> announce(@AuthenticationPrincipal Long user,@RequestBody Map<String,Object> input){admin(user);String title=Objects.toString(input.get("title"),"").trim(),body=Objects.toString(input.get("body"),"").trim();if(title.isEmpty()||title.length()>200||body.isEmpty()||body.length()>500)throw new BadRequestException("Kiểm tra tiêu đề và nội dung thông báo.");String event="admin-"+UUID.randomUUID();int count=db.update("INSERT INTO auth_db.app_notifications(user_id,event_key,type,title,body) SELECT id,?,'PROMOTION',?,? FROM auth_db.users WHERE status='ACTIVE' AND deleted_at IS NULL",event,title,body);audit(user,"BROADCAST","NOTIFICATION",0,title);return ApiResponse.success(Map.of("recipients",count));}
}
